Assert-True ($WinterPhoto.original -eq "images/originals/winter-sweet.jpg" -and $WinterPhoto.full -eq "images/web/048-winter-sweet.jpg" -and $WinterPhoto.medium -eq "images/medium/048-winter-sweet.jpg" -and $WinterPhoto.thumb -eq "images/thumbs/048-winter-sweet.jpg" -and $WinterPhoto.title -eq "WINTER 49" -and $WinterPhoto.category -eq "STILL" -and $WinterPhoto.width -eq 1920 -and $WinterPhoto.height -eq 1280 -and $WinterPhoto.mediumWidth -eq 1280 -and $WinterPhoto.mediumHeight -eq 853 -and $WinterPhoto.thumbWidth -eq 480 -and $WinterPhoto.thumbHeight -eq 320) "rel 48 should preserve the Winter Sweet photo and all responsive image sizes"
$FlashPhoto = $Photos | Where-Object { $_.id -eq 49 } | Select-Object -First 1
Assert-True ($FlashPhoto.original -eq "images/originals/makeup-flash.jpg" -and $FlashPhoto.full -eq "images/web/049-makeup-flash.jpg" -and $FlashPhoto.medium -eq "images/medium/049-makeup-flash.jpg" -and $FlashPhoto.thumb -eq "images/thumbs/049-makeup-flash.jpg" -and $FlashPhoto.title -eq "FLASH 50" -and $FlashPhoto.category -eq "PORTRAIT" -and $FlashPhoto.width -eq 1920 -and $FlashPhoto.height -eq 1920 -and $FlashPhoto.mediumWidth -eq 1280 -and $FlashPhoto.mediumHeight -eq 1280 -and $FlashPhoto.thumbWidth -eq 480 -and $FlashPhoto.thumbHeight -eq 480) "rel 49 should preserve the monochrome makeup portrait and all responsive image sizes"
$ParkPhoto = $Photos | Where-Object { $_.id -eq 32 } | Select-Object -First 1
$ParkNoteCn = -join ([char]0x4E0B, [char]0x5348, [char]0x5065, [char]0x5B8C, [char]0x8EAB, [char]0xFF0C, [char]0x518D, [char]0x53BB, [char]0x516C, [char]0x56ED, [char]0x6563, [char]0x4E86, [char]0x4F1A, [char]0x6B65, [char]0xFF0C, [char]0x597D, [char]0x6070, [char]0x610F, [char]0x3002)
$ParkLocationCn = -join ([char]0x4E1C, [char]0x839E, [char]0x20, [char]0x4E2D, [char]0x5FC3, [char]0x5E7F, [char]0x573A, [char]0x516C, [char]0x56ED)
Assert-True ($ParkPhoto.full -eq "images/web/032-r0011433.jpg" -and $ParkPhoto.note -eq $ParkNoteCn -and $ParkPhoto.noteCn -eq $ParkNoteCn -and $ParkPhoto.noteEn -match "went for a walk in the park" -and $ParkPhoto.locationCn -eq $ParkLocationCn -and $ParkPhoto.locationEn -eq "Dongguan Central Square Park") "rel 32 should preserve its bilingual park note and Dongguan location"
