foreach ($Expected in $AdditionalPhotoNotes) {
    $Photo = $Photos | Where-Object { $_.id -eq $Expected.id } | Select-Object -First 1
    Assert-True ($Photo.full -eq $Expected.full -and $Photo.note -eq $Photo.noteCn -and -not [string]::IsNullOrWhiteSpace($Photo.noteCn) -and -not [string]::IsNullOrWhiteSpace($Photo.locationCn) -and $Photo.locationEn -eq $Expected.locationEn -and $Photo.noteEn -match $Expected.noteEn -and $BuildGallery -match [regex]::Escape($Expected.locationEn)) "rel $($Expected.id) should preserve its bilingual note and location without changing photo order"
}
Assert-True (($Photos.full | Select-Object -Unique).Count -eq $Photos.Count) "gallery full image list should not repeat files"
Assert-True (($Photos.thumb | Select-Object -Unique).Count -eq $Photos.Count) "gallery thumbnail image list should not repeat files"

foreach ($Src in $ImageSources) {
    Assert-True ($Src.StartsWith("images/")) "$Src should come from images/"
    Assert-True (Test-Path -LiteralPath (Join-Path $Root $Src)) "$Src should exist"
}

foreach ($Photo in $Photos) {
    Assert-True ($Photo.id -gt 0) "each photo should have a positive id"
    Assert-True (-not [string]::IsNullOrWhiteSpace($Photo.title)) "each photo should have a title"
    Assert-True (-not [string]::IsNullOrWhiteSpace($Photo.category)) "each photo should have a category"
    Assert-True (-not [string]::IsNullOrWhiteSpace($Photo.alt)) "each photo should have alt text"
    Assert-True (-not [string]::IsNullOrWhiteSpace($Photo.original)) "each photo should remember its original file"
    Assert-True (-not [string]::IsNullOrWhiteSpace($Photo.note)) "each photo should have a note placeholder"
    Assert-True ($Photo.width -gt 0 -and $Photo.height -gt 0 -and $Photo.thumbWidth -gt 0 -and $Photo.thumbHeight -gt 0) "each photo should include stable full and thumbnail dimensions"
}

Assert-True (-not [string]::IsNullOrWhiteSpace($PhotoData.generatedAt)) "photos.json should include generation metadata"
Assert-True ($Photos.Count -ge 1) "photos.json should wrap photos in an items array"
Assert-True ($PhotoData.mediumMax -eq 1280 -and @($Photos | Where-Object { -not $_.medium -or $_.mediumWidth -le 0 -or $_.mediumHeight -le 0 }).Count -eq 0) "photos should include measured 1280px medium sources"
Assert-True (@($Photos | Where-Object { -not (Test-Path -LiteralPath (Join-Path $Root $_.medium)) }).Count -eq 0) "every medium photo source should exist"
Assert-True ($AllText -match 'assets/app\.js\?v=v143-gallery-notes1' -and $AllText -match 'assets/styles\.css\?v=v143-gallery-notes1') "release pages should use the current gallery and notes cache key"
Assert-True ($Focus -match 'assets/app\.js\?v=v143-gallery-notes1' -and $Focus -match 'assets/styles\.css\?v=v143-gallery-notes1') "focus should use the current release cache key"
Assert-True ($Css -match '@font-face[\s\S]*font-family:\s*"L4RXX Notes"' -and $Css -match 'fonts/yozai-notes\.woff2' -and $Css -match '\.focus-notes__location[\s\S]*font-family:\s*var\(--font-notes\)[\s\S]*font-weight:\s*700' -and $Css -match '\.focus-notes__text[\s\S]*font-family:\s*var\(--font-notes\)') "focus note locations should be bold while locations and copy share the locally hosted handwriting font"
Assert-True ($Work -match 'data-work-count' -and $Work -match 'data-work-years' -and $Work -match 'data-work-view="grid"' -and $Work -match 'data-work-view="list"') "work should expose its archive summary and both view controls"
Assert-True ($App -match 'data-grid-sizes' -and $App -match 'data-srcset' -and $App -match 'tabletSizes' -and $App -match 'work-item--panorama' -and $App -match 'min\(36vw, 52rem\)' -and $Css -match '\.work-item:nth-child\(-n \+ 8\)' -and $Css -match '\.work-item:nth-child\(12n \+ 12\)' -and $Css -match '\.work-item:nth-child\(8n \+ 5\)[\s\S]*grid-column:\s*1 / -1') "work should load responsive images and use varied collage placements while animating only its opening items"
Assert-True ($App -match "workViewAnimation" -and $App -match "workViewRunId" -and $App -match 'setWorkView\([^\r\n]+\{ animate: false \}\)' -and $App -match 'duration:\s*110' -and $App -match 'duration:\s*260' -and $Css -match '@media \(min-width: 769px\) and \(hover: hover\) and \(pointer: fine\)[\s\S]*\.work-item:hover \.work-item__image img') "work view switching should be interruptible while hover motion stays desktop-pointer only"
